<?php require __DIR__.'/../bootstrap.php';require_login();$s=db()->prepare('SELECT * FROM notes WHERE user_id=? ORDER BY is_pinned DESC,updated_at DESC');$s->execute([current_user()['id']]);$ns=$s->fetchAll();$title='Notes';require __DIR__.'/../includes/header.php';?><div class="page-head"><h1>Notes</h1><a class="btn" href="/notes/create/">+ New Note</a></div><div class="notes-grid"><?php foreach($ns as $n):?><article class="card setting-target" id="note-<?=$n['id']?>"><b><?=$n['is_pinned']?'📌 ':''?><?=e($n['title'])?></b><p><?=nl2br(e(substr($n['content'],0,280)))?></p><a href="/notes/edit/?id=<?=$n['id']?>" class="edit-btn">Edit</a></article><?php endforeach;?></div><?php require __DIR__.'/../includes/footer.php'; ?>